.cookie-consent {
  position: fixed;
  right: clamp(16px, 3vw, 36px);
  bottom: clamp(16px, 3vw, 36px);
  z-index: 1300;
  width: min(570px, calc(100vw - 32px));
  padding: 18px;
  display: grid;
  grid-template-columns: 68px minmax(0, 1fr);
  gap: 10px 16px;
  align-items: center;
  color: #f8f7ff;
  border: 1px solid rgba(196, 181, 253, 0.24);
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(15, 10, 31, 0.97), rgba(49, 46, 129, 0.96));
  box-shadow: 0 24px 70px rgba(15, 10, 31, 0.42);
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.cookie-consent.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.cookie-consent-icon {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(196, 181, 253, 0.2);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(124, 58, 237, 0.1));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.11);
}

.cookie-consent-icon svg {
  width: 62px;
  height: 62px;
  overflow: visible;
}

.cookie-consent h2 {
  margin: 0 0 6px;
  color: #fff;
  font-family: 'Montserrat', sans-serif;
  font-size: 1.05rem;
  line-height: 1.3;
}

.cookie-consent p {
  margin: 0;
  color: rgba(248, 247, 255, 0.76);
  font-size: 0.86rem;
  line-height: 1.55;
}

.cookie-consent-actions {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.cookie-consent button {
  min-height: 44px;
  padding: 10px 16px;
  border-radius: 13px;
  font: 700 0.84rem 'Inter', sans-serif;
  cursor: pointer;
}

.cookie-consent-accept {
  color: #fff;
  border: 1px solid transparent;
  background: linear-gradient(135deg, #6d28d9, #8b5cf6);
  box-shadow: 0 10px 24px rgba(124, 58, 237, 0.28);
}

.cookie-consent-reject {
  color: #ddd6fe;
  border: 1px solid rgba(221, 214, 254, 0.22);
  background: rgba(255, 255, 255, 0.06);
}

.cookie-settings-button {
  padding: 0;
  color: inherit;
  border: 0;
  background: none;
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

@media (max-width: 640px) {
  .cookie-consent {
    left: 12px;
    right: 12px;
    bottom: calc(12px + env(safe-area-inset-bottom));
    width: auto;
    padding: 18px;
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 10px 14px;
  }

  .cookie-consent-icon {
    width: 58px;
    height: 58px;
    border-radius: 17px;
  }

  .cookie-consent-icon svg {
    width: 54px;
    height: 54px;
  }

  .cookie-consent-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .cookie-consent button {
    font-size: 0.8rem;
  }
}

@media (max-width: 390px) {
  .cookie-consent-actions {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cookie-consent {
    transition: none;
  }
}


    :root{--primary:#7c3aed;--primary-dark:#5b21b6;--accent:#a78bfa;--text:#f8f7ff;--muted:rgba(248,247,255,.68);--line:rgba(255,255,255,.11)}
    *{box-sizing:border-box;margin:0;padding:0}
    html{color-scheme:dark}
    body{min-width:320px;min-height:100vh;overflow-x:hidden;color:var(--text);background:radial-gradient(circle at 82% 8%,rgba(124,58,237,.2),transparent 30rem),radial-gradient(circle at 8% 82%,rgba(49,46,129,.22),transparent 34rem),#0f0a1f;font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;line-height:1.65}
    body::before{position:fixed;inset:0;z-index:-2;background-image:linear-gradient(rgba(255,255,255,.02) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.02) 1px,transparent 1px);background-size:72px 72px;mask-image:linear-gradient(to bottom,black,transparent 86%);content:'';pointer-events:none}
    .glow{position:fixed;z-index:-1;width:360px;height:360px;border-radius:50%;background:rgba(124,58,237,.16);filter:blur(80px);pointer-events:none;animation:drift 8s ease-in-out infinite alternate}
    .glow-one{top:8%;right:-100px}.glow-two{bottom:-140px;left:-80px;animation-delay:-4s}
    .page{width:min(1180px,90%);min-height:100vh;margin:0 auto;padding:52px 0;display:flex;flex-direction:column}
    .brand{align-self:flex-start;text-decoration:none;font-family:'Montserrat',sans-serif;font-size:1.7rem;font-weight:900;letter-spacing:2.5px;background:linear-gradient(135deg,#5b21b6 0%,#7c3aed 50%,#a78bfa 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
    .error-card{position:relative;width:100%;margin:auto 0;padding:clamp(2rem,6vw,4.5rem);display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.2fr);gap:clamp(2.5rem,7vw,6rem);align-items:center;overflow:hidden;border:1px solid var(--line);border-radius:36px;background:linear-gradient(135deg,rgba(91,33,182,.4),rgba(33,23,70,.74));box-shadow:0 35px 90px rgba(0,0,0,.32);-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px)}
    .error-card::after{position:absolute;right:-130px;bottom:-220px;width:480px;height:480px;border-radius:50%;background:rgba(139,92,246,.19);content:'';pointer-events:none}
    .visual{position:relative;z-index:1;min-height:300px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.1);border-radius:30px;background:linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.025));box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 24px 55px rgba(0,0,0,.22)}
    .visual::before,.visual::after{position:absolute;border-radius:50%;content:''}
    .visual::before{width:152px;height:152px;border:1px solid rgba(167,139,250,.24);animation:spin 13s linear infinite}
    .visual::after{width:10px;height:10px;top:50%;left:calc(50% + 75px);background:#a78bfa;box-shadow:0 0 28px rgba(167,139,250,.95)}
    .code{position:relative;font-family:'Montserrat',sans-serif;font-size:clamp(4.6rem,10vw,8.2rem);font-weight:900;line-height:1;letter-spacing:-.08em;background:linear-gradient(145deg,#fff 10%,#a78bfa 58%,#6d28d9 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 16px 30px rgba(91,33,182,.38))}
    .copy{position:relative;z-index:1}
    .label{display:inline-flex;align-items:center;gap:.65rem;margin-bottom:1.15rem;color:#ddd6fe;font-size:.78rem;font-weight:700;letter-spacing:1.8px;text-transform:uppercase}
    .label::before{width:8px;height:8px;border-radius:50%;background:#8b5cf6;box-shadow:0 0 18px rgba(139,92,246,.85);content:''}
    h1{max-width:720px;margin-bottom:1.2rem;font-family:'Montserrat',sans-serif;font-size:clamp(2.3rem,5vw,4.4rem);font-weight:850;line-height:1.04;letter-spacing:-.04em}
    .description{max-width:650px;color:var(--muted);font-size:clamp(1rem,2vw,1.12rem)}
    .actions{margin-top:2rem;display:flex;flex-wrap:wrap;gap:.9rem}
    .button{min-height:54px;padding:.85rem 1.45rem;display:inline-flex;align-items:center;justify-content:center;gap:.65rem;border:1px solid rgba(255,255,255,.14);border-radius:16px;color:#fff;background:rgba(255,255,255,.07);font-weight:700;text-decoration:none;transition:transform .25s,border-color .25s,background .25s,box-shadow .25s}
    .button:hover{border-color:rgba(167,139,250,.45);background:rgba(255,255,255,.12);transform:translateY(-2px)}
    .button-primary{border-color:transparent;background:linear-gradient(135deg,var(--primary-dark),var(--primary));box-shadow:0 16px 34px rgba(91,33,182,.34)}
    .button-primary:hover{border-color:transparent;background:linear-gradient(135deg,#6d28d9,#8b5cf6);box-shadow:0 20px 42px rgba(91,33,182,.44)}
    .hint{margin-top:1.3rem;color:rgba(248,247,255,.42);font-size:.86rem}
    @keyframes drift{to{transform:translate3d(28px,-20px,0) scale(1.08)}}
    @keyframes spin{to{transform:rotate(360deg)}}
    @media(max-width:820px){.page{padding:30px 0}.error-card{grid-template-columns:1fr;gap:2rem;border-radius:28px}.visual{min-height:220px}.visual::before{width:125px;height:125px}.visual::after{left:calc(50% + 62px)}.code{font-size:clamp(4.8rem,22vw,7rem)}}
    @media(max-width:520px){.page{width:min(92%,1180px);padding:22px 0}.brand{font-size:1.4rem}.error-card{padding:1.35rem;border-radius:23px}.visual{min-height:185px;border-radius:21px}.actions{flex-direction:column}.button{width:100%}h1{font-size:2.25rem}}
    @media(prefers-reduced-motion:reduce){.glow,.visual::before{animation:none}.button{transition:none}}

